package com.pp.shaderlod.integration.astraquad;
import java.util.*;import java.util.regex.*;import com.google.gson.*;import java.security.MessageDigest;
public final class AstraQuadInputProof {private record Proof(Object pack,boolean valid){}private static final Map<Object,Proof> PROOFS=Collections.synchronizedMap(new WeakHashMap<>());private static final Set<String> RHS=load();private AstraQuadInputProof(){}private static Set<String> load(){try(var in=AstraQuadInputProof.class.getResourceAsStream("/assets/shaderlod/astraquad/input-api.json")){if(in==null)return Set.of();byte[] b=in.readAllBytes();if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)).equals("59f6baaf62c8989385c16abaa52c1e5bc023659ee8b3a2317b863703397bc15b"))return Set.of();var s=new HashSet<String>();for(var row:JsonParser.parseString(new String(b,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray())s.add(row.getAsJsonObject().get("draw_id_rhs").getAsString().replaceAll("\\s+",""));return Set.copyOf(s);}catch(Exception|LinkageError unknown){return Set.of();}}public static int inputKind(){if(RHS.isEmpty())return -1;try(var data=AstraQuadInputProof.class.getResourceAsStream("/assets/shaderlod/astraquad/input-api.json")){if(data==null)return -1;byte[] bytes=data.readAllBytes();if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)).equals("59f6baaf62c8989385c16abaa52c1e5bc023659ee8b3a2317b863703397bc15b"))return -1;for(var row:JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray()){var v=row.getAsJsonObject();try(var in=AstraQuadInputProof.class.getClassLoader().getResourceAsStream(v.get("producer_class_resource").getAsString())){if(in!=null&&HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(in.readAllBytes())).equals(v.get("producer_sha256").getAsString()))return v.get("input_kind").getAsInt();}}}catch(Exception|LinkageError unknown){}return -1;}private static String clean(String s){return s.replaceAll("(?s)/\\*.*?\\*/"," ").replaceAll("(?m)//[^\\r\\n]*"," ");}public static boolean inspect(Map<?,String> stages){if(stages==null||RHS.isEmpty())return false;String vertex=null;for(var row:stages.entrySet()){String text=row.getValue();if(text==null)continue;String kind=row.getKey().toString();if(!Set.of("VERTEX","FRAGMENT").contains(kind))return false;text=clean(text);if(Pattern.compile("\\b(?:gl_DrawID(?:ARB)?|gl_BaseVertex(?:ARB)?|gl_BaseInstance(?:ARB)?|gl_InstanceID(?:ARB)?|gl_PrimitiveID(?:In)?|gl_InvocationID|imageStore|atomic\\w*)\\b").matcher(text).find())return false;if(kind.equals("VERTEX"))vertex=text;}if(vertex==null)return false;var m=Pattern.compile("\\b_draw_id\\s*=\\s*([^;]+);").matcher(vertex);if(!m.find()||!RHS.contains(m.group(1).replaceAll("\\s+",""))||m.find())return false;return vertex.contains("_get_draw_translation")&&vertex.contains("u_RegionOffset");}public static void captured(Object owner,Object pack,String name,Map<?,String> stages){if(owner==null||pack==null||!"gbuffers_terrain".equals(name))return;boolean valid=inspect(stages);synchronized(PROOFS){var old=PROOFS.get(owner);PROOFS.put(owner,new Proof(pack,valid&&(old==null||old.pack()==pack&&old.valid())));}}public static boolean current(Object owner,Object pack){synchronized(PROOFS){var p=PROOFS.get(owner);return p!=null&&p.pack()==pack&&p.valid();}}}
